-- ============================================
-- LUMA — Thème 7 : MOYEN 3/3 x4 — Un cadeau à trouver dans l'urgence
-- ============================================


update scenarios set content = '{"characters": {"clerk": "le vendeur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You just remembered — your coworker''s birthday party is in one hour and you have no gift!)", "text_fr": "(Vous venez de vous rappeler — la fête d''anniversaire de votre collègue est dans une heure et vous n''avez aucun cadeau !)", "choices": [{"text": "(Rush into the nearest gift shop.)", "text_fr": "(Précipite-toi dans le magasin de cadeaux le plus proche.)", "next": "n2"}, {"text": "(Call the store to ask if they can help you find something fast.)", "text_fr": "(Appelle le magasin pour demander de l''aide à trouver quelque chose rapidement.)", "next": "n2b"}]}, "n2": {"speaker": "clerk", "text": "Welcome! You seem like you''re in a hurry, can I help you find something?", "text_fr": "Bienvenue ! Vous semblez pressé, je peux vous aider à trouver quelque chose ?", "choices": [{"text": "Yes, I need a birthday gift, but I barely know this person''s taste!", "text_fr": "Oui, j''ai besoin d''un cadeau d''anniversaire, mais je connais à peine les goûts de cette personne !", "next": "n3"}]}, "n2b": {"speaker": "clerk", "text": "(On the phone) Of course, tell me a bit about the person and I''ll suggest some ideas.", "text_fr": "(Au téléphone) Bien sûr, parlez-moi un peu de la personne et je vais suggérer des idées.", "choices": [{"text": "They''re a coworker, pretty reserved, likes coffee I think.", "text_fr": "C''est une collègue, assez réservée, aime le café je pense.", "next": "n3"}]}, "n3": {"speaker": "clerk", "text": "No worries, that happens a lot! What do you know about them — hobbies, interests?", "text_fr": "T''inquiète, ça arrive souvent ! Qu''est-ce que vous savez sur elle — passe-temps, intérêts ?", "choices": [{"text": "I know she loves coffee and reads a lot on her breaks.", "text_fr": "Je sais qu''elle adore le café et lit beaucoup pendant ses pauses.", "next": "n4"}, {"text": "Honestly, not much — we don''t talk outside of work projects.", "text_fr": "Honnêtement, pas grand-chose — on parle pas en dehors des projets de travail.", "next": "n4b"}]}, "n4": {"speaker": "clerk", "text": "Perfect, I have some great options — a nice mug set or a small book with a coffee theme.", "text_fr": "Parfait, j''ai de bonnes options — un joli service à café ou un petit livre sur le thème du café.", "choices": [{"text": "The mug set sounds perfect, something safe but thoughtful.", "text_fr": "Le service à café a l''air parfait, quelque chose de sûr mais attentionné.", "next": "n5"}, {"text": "Actually, could you show me both so I can decide?", "text_fr": "En fait, vous pourriez me montrer les deux pour que je décide ?", "next": "n5"}]}, "n4b": {"speaker": "clerk", "text": "That''s okay, something universally appreciated like a nice candle or a small plant usually works well.", "text_fr": "C''est pas grave, quelque chose de généralement apprécié comme une belle bougie ou une petite plante marche bien généralement.", "choices": [{"text": "A candle sounds like a safe, thoughtful choice.", "text_fr": "Une bougie semble être un choix sûr et attentionné.", "next": "n5"}]}, "n5": {"speaker": "clerk", "text": "Great pick! I''ll gift wrap it for you quickly since you''re short on time.", "text_fr": "Excellent choix ! Je vous l''emballe rapidement vu que vous manquez de temps.", "choices": [{"text": "Thank you so much, that''s incredibly helpful.", "text_fr": "Merci beaucoup, c''est incroyablement utile.", "next": "n6"}]}, "n6": {"speaker": "clerk", "text": "Would you like a card to go with it? We have some nice generic ones by the register.", "text_fr": "Vous voulez une carte pour accompagner ça ? On a de belles cartes génériques près de la caisse.", "choices": [{"text": "Yes, that would be perfect, thank you for thinking of that.", "text_fr": "Oui, ce serait parfait, merci d''y avoir pensé.", "next": "n7"}, {"text": "No need, I think the gift speaks for itself.", "text_fr": "Pas besoin, je pense que le cadeau parle de lui-même.", "next": "n7"}]}, "n7": {"speaker": "clerk", "text": "All set! You''re going to make it just in time.", "text_fr": "Tout est prêt ! Vous allez y arriver juste à temps.", "choices": [{"text": "Thank you so much for saving me today, seriously.", "text_fr": "Merci beaucoup de m''avoir sauvé aujourd''hui, sérieusement.", "next": "end_saved"}]}, "end_saved": {"speaker": "clerk", "text": "Happy to help! Enjoy the party.", "text_fr": "Content d''avoir aidé ! Profitez de la fête.", "end": true, "ending_label": "Cadeau trouvé juste à temps 🎁⏰✅"}}}'::jsonb, is_playable = true
where title = 'Un cadeau à trouver dans l''''urgence'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
